func (this *Blofin) watchOrdersForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	limit := ccxt.GetArg(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params

	ccxt.PanicOnError((<-this.AuthenticateAsync()))
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var trigger *bool = this.SafeBool2(params, "stop", "trigger")
	params = ccxt.MapTyped(this.Omit(params, []any{"stop", "trigger"}))
	var channel string = func() string {
		if trigger != nil && *trigger == true {
			return "orders-algo"
		}
		return "orders"
	}()

	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.WatchMultipleWrapperAsync(false, channel, "watchOrdersForSymbols", symbols, params))))
	if this.NewUpdates {
		var first map[string]any = ccxt.SafeMapTyped(orders, 0)
		var tradeSymbol *string = this.SafeString(first, "symbol")
		limit = ccxt.ToGetsLimit(orders).GetLimit(tradeSymbol, limit)
	}

	ch <- this.FilterBySinceLimit(orders, since, limit, "timestamp", true)
	return nil
}
func (this *Blofin) HandleOrders(client any, message map[string]any) {
	//
	//     {
	//         action: 'update',
	//         arg: { channel: 'orders' },
	//         data: [
	//           <same object as shown in REST example>
	//         ]
	//     }
	//
	if ccxt.IsEqual(this.Orders, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var orders any = this.Orders
	var arg map[string]any = ccxt.SafeMapTyped(message, "arg")
	var channelName *string = this.SafeString(arg, "channel")
	var data []any = ccxt.SafeListTyped(message, "data")
	for i := 0; i < len(data); i++ {
		var order map[string]any = ccxt.MapTyped(this.ParseWsOrder(func() any {
			if i >= 0 && i < len(data) {
				return ccxt.DerefScalar(data[i])
			}
			return nil
		}()))
		var symbol *string = ccxt.SafeStringPtr(order["symbol"])
		var messageHash any = ccxt.Add(ccxt.Add(channelName, ":"), symbol)
		orders.(ccxt.Appender).Append(order)
		client.(ccxt.ClientInterface).Resolve(orders, messageHash)
		client.(ccxt.ClientInterface).Resolve(orders, channelName)
	}
}
